from cardio_1 import a, G
# C85 — Lymphome non hodgkinien, de types autres et non précisés (H-08-Hématologie, cycle Betta 33).
# Entrées conditionnelles : aucun terme déjà présent dans G n'est écrasé.
# Les sigles dont le développement n'est pas fourni par le dossier de recherche sont signalés comme tels, sans invention.

def _add(k, lit, full, d, ref=None):
    if k not in G:
        a(k, lit, full, '<p>' + d + '</p>', ref)

_cd = lambda n: [('CD', 'Cluster of Differentiation (groupe de différenciation)'), (n, 'numéro du marqueur')]
for n, d in [('10', 'Marqueur typiquement négatif dans le lymphome médiastinal primitif (ESMO 2016).'),
             ('15', 'Marqueur négatif dans le lymphome médiastinal primitif ; son absence est un argument contre un lymphome de Hodgkin classique (ESMO 2016 ; Nappi 2025).'),
             ('21', 'Marqueur typiquement négatif dans le lymphome médiastinal primitif (ESMO 2016).'),
             ('22', 'Marqueur pan-B exprimé par les grandes cellules du lymphome médiastinal primitif (ESMO 2016).'),
             ('23', 'Marqueur souvent positif dans le lymphome médiastinal primitif ; argument en faveur de l’entité (ESMO 2016 ; Nappi 2025).'),
             ('58', 'Gène dont des mutations sont décrites dans l’échappement immunitaire du lymphome médiastinal primitif (Chen 2021).'),
             ('274', 'Autre nom du gène de PD-L1, amplifié ou transloqué avec 9p24.1 dans le lymphome médiastinal primitif.')]:
    _add('CD' + n, _cd(n), 'Marqueur CD' + n, d, 'c85-phenotype')
_add('CD79a', [('CD', 'Cluster of Differentiation (groupe de différenciation)'), ('79a', 'numéro 79a')], 'Marqueur CD79a', 'Marqueur pan-B positif dans le lymphome médiastinal primitif (ESMO 2016).', 'c85-phenotype')
_add('MAL', [('MAL', 'nom de la protéine MAL ; le dossier de recherche n’en donne pas le développement')], 'Protéine MAL (marqueur)', 'Marqueur positif dans environ 70 % des lymphomes médiastinaux primitifs (ESMO 2016 ; Nappi 2025).', 'c85-phenotype')
_add('BCL6', [('BCL6', 'nom de gène (B-cell lymphoma 6) ; marqueur variable dans cette entité')], 'Marqueur BCL6', 'Variable dans le lymphome médiastinal primitif, donc non discriminant seul.', 'c85-phenotype')
_add('IRF4', [('IRF4', 'nom de gène (interferon regulatory factor 4) ; marqueur variable dans cette entité')], 'Marqueur IRF4', 'Variable dans le lymphome médiastinal primitif, donc non discriminant seul.', 'c85-phenotype')
_add('hCG', [('h', 'human (humaine)'), ('CG', 'Chorionic Gonadotropin (gonadotrophine chorionique)')], 'Gonadotrophine chorionique humaine', 'La fraction bêta (β-hCG) est élevée, avec l’alpha-fœtoprotéine, dans les tumeurs germinales non séminomateuses du médiastin (Juanpere 2013).', 'c85-diff-germinale')
_add('AgHBs', [('Ag', 'Antigène'), ('HBs', 'de surface du virus de l’hépatite B')], 'Antigène de surface du virus de l’hépatite B', 'Avec l’anti-HBc, il se recherche avant le rituximab, car la réactivation du virus de l’hépatite B peut être fulminante (information professionnelle suisse de MabThera®).', 'c85-mabthera')

_add('DLBCL', [('D', 'Diffuse (diffus)'), ('L', 'Large (à grandes)'), ('B', 'B-'), ('C', 'Cell (cellules)'), ('L', 'Lymphoma (lymphome)')], 'Lymphome diffus à grandes cellules B', 'Lymphome agressif à grandes cellules B, entité la plus fréquente des lymphomes à grandes cellules B.', 'c85-dlbcl-nos')
_add('NOS', [('N', 'Not (non)'), ('O', 'Otherwise (autrement)'), ('S', 'Specified (spécifié)')], 'Sans autre précision (not otherwise specified)', 'Désigne une entité définie par l’absence des critères d’une entité plus spécifique (classification de l’OMS, 5e édition).', 'c85-dlbcl-nos')
_add('MGZL', [('M', 'Mediastinal (médiastinal)'), ('GZ', 'Grey Zone (zone grise)'), ('L', 'Lymphoma (lymphome)')], 'Lymphome de la zone grise médiastinale', 'Entité propre au médiastin qui remplace la catégorie « lymphome B inclassable, intermédiaire entre DLBCL et lymphome de Hodgkin classique ».', 'c85-mgzl')
_add('HGBL', [('H', 'High (haut)'), ('G', 'Grade (grade)'), ('B', 'B-'), ('L', 'Lymphoma (lymphome)')], 'Lymphome B de haut grade', 'Lymphome B agressif à cellules moyennes ou blastoïdes ; HGBL, NOS désigne ceux qui n’entrent dans aucune entité définie.', 'c85-hgbl')
_add('ICC', [('I', 'International'), ('C', 'Consensus'), ('C', 'Classification')], 'Classification de consensus international', 'Classification publiée en 2022 en parallèle de celle de l’OMS (Campo et al.) ; son rapport n’a pas été lu en texte intégral pour ce chapitre.', 'c85-sources-guides')
_add('SAI', [('S', 'Sans'), ('A', 'Autre'), ('I', 'Indication')], 'Sans autre indication', 'Mention de la CIM-10-GM : « lymphome malin SAI », « lymphome SAI », « lymphome non hodgkinien SAI » sont les inclusions de C85.9.', 'c85-cim')
for code, lab in [('C85.1', 'Lymphome à cellules B, sans précision'), ('C85.2', 'Lymphome médiastinal (thymique) à grandes cellules B'), ('C85.7', 'Autres types précisés de lymphome non hodgkinien'), ('C85.9', 'Lymphome non hodgkinien, non précisé'), ('C83.3', 'Lymphome diffus à grandes cellules B'), ('C83.8', 'Autres lymphomes non folliculaires')]:
    _add(code, [(code, 'code de la CIM-10-GM 2024 (chapitre des tumeurs) : ' + lab)], lab + ' (' + code + ')', 'Code de la CIM-10-GM 2024. ' + ('C85.2 exclut C83.3 et C83.8.' if code == 'C85.2' else 'Voir la fenêtre de lecture des sous-codes de C85.'), 'c85-cim')

_add('CIITA', [('CIITA', 'class II major histocompatibility complex transactivator (transactivateur des molécules de classe II)')], 'Transactivateur des molécules HLA de classe II', 'Son réarrangement fait baisser l’expression des molécules HLA de classe II et facilite l’échappement immunitaire ; il est associé à une survie spécifique plus courte (Chen 2021).', 'c85-ciita')
_add('REL', [('REL', 'nom de gène (proto-oncogène REL, sous-unité de NF-κB) ; localisation 2p16')], 'Gène REL', 'Son amplification (2p16) active la voie NF-κB dans le lymphome médiastinal primitif (ESMO 2016).', 'c85-nfkb')
_add('TNFAIP3', [('TNFAIP3', 'Tumor Necrosis Factor Alpha-Induced Protein 3')], 'Gène TNFAIP3', 'Ses mutations inactivatrices maintiennent la voie NF-κB activée dans le lymphome médiastinal primitif.', 'c85-nfkb')
_add('SOCS1', [('SOCS1', 'Suppressor Of Cytokine Signaling 1')], 'Suppresseur de la signalisation des cytokines 1', 'Ses mutations inactivatrices maintiennent la voie JAK-STAT activée.', 'c85-jakstat')
_add('STAT6', [('STAT6', 'Signal Transducer and Activator of Transcription 6')], 'Facteur STAT6', 'Sa signalisation, avec la surexpression d’IL-13, participe à l’activation de la voie JAK-STAT.', 'c85-jakstat')
_add('B2M', [('B2M', 'bêta-2-microglobuline')], 'Bêta-2-microglobuline', 'Ses mutations contribuent à l’échappement immunitaire du lymphome médiastinal primitif.', 'c85-echappement')
_add('PDCD1LG2', [('PDCD1LG2', 'Programmed Cell Death 1 Ligand 2')], 'Gène du ligand 2 de la mort cellulaire programmée (PD-L2)', 'Amplifié ou transloqué avec 9p24.1 dans le lymphome médiastinal primitif.', 'c85-echappement')

_add('IELSG37', [('IELSG', 'International Extranodal Lymphoma Study Group'), ('37', 'numéro de l’essai')], 'Essai 37 de l’International Extranodal Lymphoma Study Group', 'Essai randomisé de non-infériorité sur l’omission de la radiothérapie dans le lymphome médiastinal primitif en réponse métabolique complète (Martelli et al.).', 'c85-ielsg37')
_add('IOR', [('IOR', 'Istituto Oncologico di Ricerca (Bellinzona)')], 'Institut d’oncologie de recherche de Bellinzone', 'Coordonne l’essai IELSG37.', 'c85-ielsg37')
_add('IOSI', [('IOSI', 'Istituto Oncologico della Svizzera Italiana')], 'Institut d’oncologie de la Suisse italienne', 'Co-coordonne l’essai IELSG37.', 'c85-ielsg37')
