_add('OeGHO', [('Oe', 'Österreichische (autrichienne)'), ('G', 'Gesellschaft (société)'), ('H', 'für Hämatologie (d’hématologie)'), ('O', 'und Onkologie (et d’oncologie)')], 'Société autrichienne d’hématologie et d’oncologie médicale', 'Co-éditrice de la recommandation Onkopedia sur le lymphome diffus à grandes cellules B (12/2025).', 'c85-sources-guides')
_add('LYSA', [('LY', 'LYmphoma (lymphome)'), ('S', 'Study (étude)'), ('A', 'Association')], 'Lymphoma Study Association', 'Groupe francophone dont les recommandations pragmatiques de 2025 sur le lymphome médiastinal primitif n’ont été lues qu’en résumé.', 'c85-sources-guides')
