_add('CHOP-21', [('CHOP', 'Cyclophosphamide, Hydroxydaunorubicine, Oncovin, Prednisone'), ('21', 'cycles de 21 jours (toutes les 3 semaines)')], 'CHOP administré toutes les 3 semaines', 'Comparateur de la méta-analyse de Cook et al. avec R-CHOP-21.', 'c85-rchop')
_add('R-CHOP14', [('R', 'Rituximab'), ('CHOP', 'Cyclophosphamide, Hydroxydaunorubicine, Oncovin, Prednisone'), ('14', 'nom du schéma cité par ESMO 2016 ; le dossier n’en précise pas l’intervalle')], 'R-CHOP14', 'Schéma cité comme standard par ESMO 2016.', 'c85-rchop')
